-- Dua Medical HMS: database schema for Supabase (generated by scripts/export_schema_sql.py).
-- Run once on an EMPTY database in Supabase > SQL Editor. Safe to read; do not edit by hand.

BEGIN;

-- ================================================================ tables
CREATE TABLE departments (
	id UUID NOT NULL, 
	code VARCHAR(30) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	UNIQUE (name)
);

CREATE TABLE document_sequences (
	name VARCHAR(60) NOT NULL, 
	last_value INTEGER NOT NULL, 
	PRIMARY KEY (name)
);

CREATE TABLE hospitals (
	id UUID NOT NULL, 
	name VARCHAR(180) NOT NULL, 
	code VARCHAR(30) NOT NULL, 
	address TEXT, 
	phone VARCHAR(30), 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	UNIQUE (code)
);

CREATE TABLE medicines (
	id UUID NOT NULL, 
	medicine_code VARCHAR(40) NOT NULL, 
	generic_name VARCHAR(180) NOT NULL, 
	brand_name VARCHAR(180), 
	strength VARCHAR(80), 
	dosage_form VARCHAR(80), 
	category VARCHAR(80), 
	unit VARCHAR(30) DEFAULT 'unit' NOT NULL, 
	reorder_level NUMERIC(14, 3) DEFAULT '0' NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (medicine_code)
);

CREATE TABLE permissions (
	id UUID NOT NULL, 
	key VARCHAR(120) NOT NULL, 
	module VARCHAR(80) NOT NULL, 
	description VARCHAR(255), 
	PRIMARY KEY (id), 
	UNIQUE (key)
);

CREATE TABLE roles (
	id UUID NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	description VARCHAR(255), 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE suppliers (
	id UUID NOT NULL, 
	name VARCHAR(180) NOT NULL, 
	contact_person VARCHAR(120), 
	phone VARCHAR(30), 
	address TEXT, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE users (
	id UUID NOT NULL, 
	username VARCHAR(80) NOT NULL, 
	email VARCHAR(255), 
	phone VARCHAR(30), 
	password_hash VARCHAR(255) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	is_superuser BOOLEAN NOT NULL, 
	must_change_password BOOLEAN NOT NULL, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (username), 
	UNIQUE (email)
);

CREATE TABLE audit_logs (
	id UUID NOT NULL, 
	actor_user_id UUID, 
	action VARCHAR(80) NOT NULL, 
	entity_type VARCHAR(100) NOT NULL, 
	entity_id VARCHAR(80) NOT NULL, 
	old_values JSONB, 
	new_values JSONB, 
	ip_address INET, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(actor_user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE employees (
	id UUID NOT NULL, 
	user_id UUID, 
	department_id UUID NOT NULL, 
	employee_code VARCHAR(40) NOT NULL, 
	full_name VARCHAR(180) NOT NULL, 
	designation VARCHAR(100) NOT NULL, 
	employment_status VARCHAR(30) NOT NULL, 
	joining_date DATE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(department_id) REFERENCES departments (id), 
	UNIQUE (employee_code)
);

CREATE TABLE hospital_settings (
	id UUID NOT NULL, 
	hospital_id UUID NOT NULL, 
	currency VARCHAR(10) NOT NULL, 
	timezone VARCHAR(80) NOT NULL, 
	locale VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (hospital_id), 
	FOREIGN KEY(hospital_id) REFERENCES hospitals (id)
);

CREATE TABLE inventory_locations (
	id UUID NOT NULL, 
	code VARCHAR(40) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	department_id UUID, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);

CREATE TABLE medicine_batches (
	id UUID NOT NULL, 
	medicine_id UUID NOT NULL, 
	batch_number VARCHAR(80) NOT NULL, 
	expiry_date DATE NOT NULL, 
	purchase_price NUMERIC(14, 2) NOT NULL, 
	selling_price NUMERIC(14, 2) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_batch_prices_nonnegative CHECK (purchase_price >= 0 AND selling_price >= 0), 
	CONSTRAINT uq_batch_medicine_number UNIQUE (medicine_id, batch_number), 
	FOREIGN KEY(medicine_id) REFERENCES medicines (id)
);

CREATE TABLE notifications (
	id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	title VARCHAR(180) NOT NULL, 
	body TEXT, 
	is_read BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE patients (
	id UUID NOT NULL, 
	mrn VARCHAR(40) NOT NULL, 
	user_id UUID, 
	first_name VARCHAR(100) NOT NULL, 
	last_name VARCHAR(100), 
	date_of_birth DATE, 
	gender VARCHAR(30), 
	blood_group VARCHAR(5), 
	phone VARCHAR(30) NOT NULL, 
	email VARCHAR(255), 
	address TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX ix_patients_mrn ON patients (mrn);
CREATE INDEX ix_patients_phone ON patients (phone);

CREATE TABLE pharmacy_purchases (
	id UUID NOT NULL, 
	purchase_number VARCHAR(50) NOT NULL, 
	supplier_id UUID NOT NULL, 
	supplier_invoice_no VARCHAR(80), 
	purchase_date DATE NOT NULL, 
	total_amount NUMERIC(14, 2) NOT NULL, 
	notes TEXT, 
	created_by UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_purchase_total_nonnegative CHECK (total_amount >= 0), 
	UNIQUE (purchase_number), 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id), 
	FOREIGN KEY(created_by) REFERENCES users (id)
);

CREATE TABLE role_permissions (
	role_id UUID NOT NULL, 
	permission_id UUID NOT NULL, 
	PRIMARY KEY (role_id, permission_id), 
	FOREIGN KEY(role_id) REFERENCES roles (id) ON DELETE CASCADE, 
	FOREIGN KEY(permission_id) REFERENCES permissions (id) ON DELETE CASCADE
);

CREATE TABLE tasks (
	id UUID NOT NULL, 
	title VARCHAR(180) NOT NULL, 
	description TEXT, 
	status VARCHAR(30) NOT NULL, 
	priority VARCHAR(30) NOT NULL, 
	due_at TIMESTAMP WITH TIME ZONE, 
	created_by UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(created_by) REFERENCES users (id)
);

CREATE TABLE user_roles (
	user_id UUID NOT NULL, 
	role_id UUID NOT NULL, 
	PRIMARY KEY (user_id, role_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(role_id) REFERENCES roles (id) ON DELETE CASCADE
);

ALTER TABLE user_roles ADD CONSTRAINT uq_user_role UNIQUE (user_id, role_id);

CREATE TABLE user_sessions (
	id UUID NOT NULL, 
	user_id UUID NOT NULL, 
	refresh_token_hash VARCHAR(128) NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	revoked_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	UNIQUE (refresh_token_hash)
);

CREATE TABLE encounters (
	id UUID NOT NULL, 
	patient_id UUID NOT NULL, 
	doctor_employee_id UUID NOT NULL, 
	encounter_type VARCHAR(30) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	ended_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(doctor_employee_id) REFERENCES employees (id)
);

CREATE TABLE invoices (
	id UUID NOT NULL, 
	invoice_number VARCHAR(50) NOT NULL, 
	patient_id UUID NOT NULL, 
	invoice_date DATE NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	subtotal NUMERIC(14, 2) NOT NULL, 
	discount_amount NUMERIC(14, 2) NOT NULL, 
	tax_amount NUMERIC(14, 2) NOT NULL, 
	total_amount NUMERIC(14, 2) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_invoice_nonnegative CHECK (subtotal >= 0 AND discount_amount >= 0 AND tax_amount >= 0 AND total_amount >= 0), 
	CONSTRAINT ck_invoice_currency_pkr CHECK (currency = 'PKR'), 
	CONSTRAINT ck_invoice_status CHECK (status IN ('DRAFT','UNPAID','PARTIALLY_PAID','PAID','CANCELLED','VOID')), 
	UNIQUE (invoice_number), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
);

CREATE TABLE patient_allergies (
	id UUID NOT NULL, 
	patient_id UUID NOT NULL, 
	allergy_name VARCHAR(160) NOT NULL, 
	severity VARCHAR(30), 
	reaction TEXT, 
	recorded_by UUID NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE CASCADE, 
	FOREIGN KEY(recorded_by) REFERENCES users (id)
);

CREATE TABLE payments (
	id UUID NOT NULL, 
	receipt_number VARCHAR(50) NOT NULL, 
	patient_id UUID NOT NULL, 
	amount NUMERIC(14, 2) NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	payment_method VARCHAR(30) NOT NULL, 
	reference_number VARCHAR(100), 
	status VARCHAR(30) NOT NULL, 
	received_by UUID NOT NULL, 
	received_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_payment_positive_amount CHECK (amount > 0), 
	CONSTRAINT ck_payment_currency_pkr CHECK (currency = 'PKR'), 
	UNIQUE (receipt_number), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(received_by) REFERENCES users (id)
);

CREATE TABLE pharmacy_purchase_items (
	id UUID NOT NULL, 
	purchase_id UUID NOT NULL, 
	medicine_id UUID NOT NULL, 
	batch_id UUID NOT NULL, 
	quantity NUMERIC(14, 3) NOT NULL, 
	unit_cost NUMERIC(14, 2) NOT NULL, 
	line_total NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_purchase_item_values CHECK (quantity > 0 AND unit_cost >= 0), 
	FOREIGN KEY(purchase_id) REFERENCES pharmacy_purchases (id) ON DELETE CASCADE, 
	FOREIGN KEY(medicine_id) REFERENCES medicines (id), 
	FOREIGN KEY(batch_id) REFERENCES medicine_batches (id)
);

CREATE TABLE stock_movements (
	id UUID NOT NULL, 
	batch_id UUID NOT NULL, 
	location_id UUID NOT NULL, 
	movement_type VARCHAR(30) NOT NULL, 
	quantity NUMERIC(14, 3) NOT NULL, 
	reference_type VARCHAR(50), 
	reference_id UUID, 
	performed_by UUID NOT NULL, 
	occurred_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_stock_movement_positive_qty CHECK (quantity > 0), 
	CONSTRAINT ck_stock_movement_type CHECK (movement_type IN ('RECEIPT','SALE','ISSUE','RETURN','TRANSFER_IN','TRANSFER_OUT','ADJUSTMENT_IN','ADJUSTMENT_OUT','EXPIRED','DAMAGE')), 
	FOREIGN KEY(batch_id) REFERENCES medicine_batches (id), 
	FOREIGN KEY(location_id) REFERENCES inventory_locations (id), 
	FOREIGN KEY(performed_by) REFERENCES users (id)
);

CREATE TABLE task_assignments (
	task_id UUID NOT NULL, 
	assignee_user_id UUID NOT NULL, 
	assigned_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (task_id, assignee_user_id), 
	FOREIGN KEY(task_id) REFERENCES tasks (id) ON DELETE CASCADE, 
	FOREIGN KEY(assignee_user_id) REFERENCES users (id) ON DELETE CASCADE
);

ALTER TABLE task_assignments ADD CONSTRAINT uq_task_assignment UNIQUE (task_id, assignee_user_id);

CREATE TABLE invoice_items (
	id UUID NOT NULL, 
	invoice_id UUID NOT NULL, 
	source_module VARCHAR(40) NOT NULL, 
	source_reference_id UUID, 
	description VARCHAR(255) NOT NULL, 
	quantity NUMERIC(14, 3) NOT NULL, 
	unit_price NUMERIC(14, 2) NOT NULL, 
	line_total NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id) ON DELETE CASCADE
);

CREATE TABLE payment_allocations (
	id UUID NOT NULL, 
	payment_id UUID NOT NULL, 
	invoice_id UUID NOT NULL, 
	allocated_amount NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_allocation_positive CHECK (allocated_amount > 0), 
	FOREIGN KEY(payment_id) REFERENCES payments (id), 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id)
);

CREATE TABLE pharmacy_sales (
	id UUID NOT NULL, 
	sale_number VARCHAR(50) NOT NULL, 
	patient_id UUID, 
	customer_name VARCHAR(180), 
	customer_phone VARCHAR(30), 
	subtotal NUMERIC(14, 2) NOT NULL, 
	discount_amount NUMERIC(14, 2) NOT NULL, 
	total_amount NUMERIC(14, 2) NOT NULL, 
	paid_amount NUMERIC(14, 2) NOT NULL, 
	payment_method VARCHAR(30), 
	invoice_id UUID, 
	sold_by UUID NOT NULL, 
	sold_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_sale_nonnegative CHECK (subtotal >= 0 AND discount_amount >= 0 AND total_amount >= 0 AND paid_amount >= 0), 
	CONSTRAINT ck_sale_paid_le_total CHECK (paid_amount <= total_amount), 
	CONSTRAINT ck_sale_walkin_paid_in_full CHECK (patient_id IS NOT NULL OR paid_amount = total_amount), 
	UNIQUE (sale_number), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id), 
	FOREIGN KEY(sold_by) REFERENCES users (id)
);

CREATE TABLE pharmacy_sale_items (
	id UUID NOT NULL, 
	sale_id UUID NOT NULL, 
	medicine_id UUID NOT NULL, 
	batch_id UUID NOT NULL, 
	quantity NUMERIC(14, 3) NOT NULL, 
	unit_price NUMERIC(14, 2) NOT NULL, 
	line_total NUMERIC(14, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_sale_item_values CHECK (quantity > 0 AND unit_price >= 0), 
	FOREIGN KEY(sale_id) REFERENCES pharmacy_sales (id) ON DELETE CASCADE, 
	FOREIGN KEY(medicine_id) REFERENCES medicines (id), 
	FOREIGN KEY(batch_id) REFERENCES medicine_batches (id)
);

-- ================================================================ security
-- Row Level Security ON with no policies = the Supabase Data API (publishable/anon key) has
-- no access to any table. The HMS API connects as the owner and is not affected.
ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.document_sequences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.hospitals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.medicines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.hospital_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.medicine_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.patients ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pharmacy_purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.role_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.encounters ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.patient_allergies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pharmacy_purchase_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stock_movements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.task_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payment_allocations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pharmacy_sales ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pharmacy_sale_items ENABLE ROW LEVEL SECURITY;

